package ca.yorku.eecs3311.coursepilot.application.agent; import org.springframework.stereotype.Service; import java.util.*; @Service public class AgentCoordinator {private final IntentAnalyzer analyzer;private final TaskPlanner planner;private final AgentPlanValidator validator;private final AgentToolManager tools;private final MemoryManager memory;private final ResponseSynthesizer synthesizer;public AgentCoordinator(IntentAnalyzer a,TaskPlanner p,AgentPlanValidator v,AgentToolManager t,MemoryManager m,ResponseSynthesizer s){analyzer=a;planner=p;validator=v;tools=t;memory=m;synthesizer=s;}public String run(Long courseId,String request){AgentIntent intent=analyzer.analyze(request);AgentPlan plan=planner.plan(intent,request);validator.validate(plan,courseId);List<AgentTool.ToolResult> results=new ArrayList<>();for(var step:plan.steps())results.add(tools.execute(step,courseId));return synthesizer.synthesize(intent,results,memory.recent(courseId));}}
